using System;
using MassiveArmy.Industrial;
using MassiveArmy.Planetary;
using UnityEngine;
namespace MassiveArmy.Networking {
    public sealed partial class SurvivalNetworkSession {
        readonly System.Collections.Generic.Dictionary<long,Peer> pendingEvaExits=new System.Collections.Generic.Dictionary<long,Peer>();
        readonly System.Collections.Generic.Dictionary<long,SpacePose> evaShipStarts=new System.Collections.Generic.Dictionary<long,SpacePose>();
        readonly System.Collections.Generic.Dictionary<Peer,FramePose> evaActorStarts=new System.Collections.Generic.Dictionary<Peer,FramePose>();
        double evaPredictionTime;
        void ResolvePredictedEvaContacts(SurvivalMotion motion,FramePose previous,PlanetSurface surface,float dt){
            double age=evaPredictionTime-(latest?.simulationSeconds??evaPredictionTime);if(age<0||age>.25)return; // Remote hull motion beyond this horizon remains server-validated.
            foreach(var ship in clientShips.Values){if(ship.pose.body!=motion.pose.body||!clientShipAssemblies.TryGetValue(ship.entity,out var layout))continue;var source=EvaShipPose(ship);SpacePose At(double seconds){var point=source;var up=PlanetPrecisionPolicy.Direction(source.position);var acceleration=new Double3(up)*(-surface.Definition.gravitationalParameter/System.Math.Max(1,source.position.Magnitude*source.position.Magnitude));if(ship.landed)acceleration=default;point.position+=source.linearVelocity*seconds+acceleration*(seconds*(seconds+dt)*.5);point.linearVelocity+=acceleration*seconds;float angle=source.angularVelocity.magnitude*(float)seconds*Mathf.Rad2Deg;if(Mathf.Abs(angle)>0)point.rotation=Quaternion.AngleAxis(angle,source.angularVelocity.normalized)*point.rotation;return point;}var start=At(System.Math.Max(0,age-dt));var end=At(age);if(SegmentDistance(start.position,end.position,SurvivalVehicleSimulation.Position(motion.pose))>ship.collisionRadius+60)continue;SurvivalEvaContacts.Resolve(motion,previous,start,end,Interior(ship,layout),out _);}
        }
        void ClearEvaTracking(){pendingEvaExits.Clear();evaShipStarts.Clear();evaActorStarts.Clear();}
        static SpacePose EvaShipPose(SurvivalShipState ship)=>new SpacePose{position=SurvivalVehicleSimulation.Position(ship.pose),rotation=ShipRotation(ship),linearVelocity=new Double3(ship.velocityX,ship.velocityY,ship.velocityZ),angularVelocity=new Vector3(ship.spinX,ship.spinY,ship.spinZ)};
        void CaptureEvaFrames(){evaActorStarts.Clear();evaShipStarts.Clear();foreach(var peer in peers.Values)if(peer.motion.eva&&authority.World.Actor(peer.record.actor).health>0)evaActorStarts[peer]=peer.motion.pose;if(evaActorStarts.Count>0)foreach(var ship in authority.World.multiplayer.ships)evaShipStarts[ship.entity]=EvaShipPose(ship);}
        void CompleteEvaTransitions(){
            foreach(var entry in evaActorStarts){var peer=entry.Key;var actor=authority.World.Actor(peer.record.actor);if(!peer.motion.eva||actor.health<=0)continue;foreach(var ship in authority.World.multiplayer.ships){if(ship.pose.body!=peer.motion.pose.body||!evaShipStarts.TryGetValue(ship.entity,out var start))continue;var end=EvaShipPose(ship);if(SegmentDistance(start.position,end.position,SurvivalVehicleSimulation.Position(peer.motion.pose))>ship.collisionRadius+(SurvivalVehicleSimulation.Position(peer.motion.pose)-SurvivalVehicleSimulation.Position(entry.Value)).Magnitude+3)continue;var model=Interior(ship,authority.World.Ship(ship.owner));if(SurvivalEvaContacts.Resolve(peer.motion,entry.Value,start,end,model,out float impact)&&impact>50){actor.health=0;break;}}actor.pose=peer.motion.pose;StoreEva(peer.motion,peer.record);}
            foreach(var entry in pendingEvaExits){var peer=entry.Value;var actor=authority.World.Actor(peer.record.actor);if(actor.health<=0)continue;var ship=authority.World.multiplayer.ships.Find(s=>s.entity==peer.record.attachedShip);if(ship==null)continue;SurvivalShipAuthority.Release(authority.World,peer.record);peer.record.attachedShip=0;peer.record.shipSeat=-1;peer.record.interiorWalking=false;DetachEva(peer.motion,ship);peer.record.evaBoardReadyTick=clock.Tick+Config.tickRate/2;peer.motion.epoch++;peer.input.Clear();StoreEva(peer.motion,peer.record);actor.pose=peer.motion.pose;}pendingEvaExits.Clear();
            foreach(var peer in peers.Values)if(peer.motion.eva&&authority.World.Actor(peer.record.actor).health>0&&peer.record.attachedShip==0){TryWalkAboard(peer);StoreEva(peer.motion,peer.record);}
        }
        static void ClearEva(SurvivalMotion motion){motion.eva=false;motion.evaVelocityX=motion.evaVelocityY=motion.evaVelocityZ=motion.evaSuitX=motion.evaSuitY=motion.evaSuitZ=0;}
        static Double3 EvaVelocity(SurvivalMotion motion)=>new Double3(motion.evaVelocityX+motion.evaSuitX,motion.evaVelocityY+motion.evaSuitY,motion.evaVelocityZ+motion.evaSuitZ);
        static Double3 ShipPointVelocity(SurvivalShipState ship,FramePose local)=>new Double3(ship.velocityX,ship.velocityY,ship.velocityZ)+new Double3(Vector3.Cross(new Vector3(ship.spinX,ship.spinY,ship.spinZ),Double3.Rotate(ShipRotation(ship),new Double3(local.x,local.y,local.z)).Float));
        static bool SpaceDoorway(SurvivalShipState ship,FramePose local)=>!ship.landed&&ship.rearOpen&&Math.Abs(local.x)<5.6&&local.y>=-4.4&&local.y<3.2&&local.z>=-40&&local.z< -37.6;
        static bool ExitingSpaceDoor(SurvivalShipState ship,FramePose previous,FramePose next)=>SpaceDoorway(ship,next)&&previous.z>=-38.5&&next.z< -38.4;
        static void DetachEva(SurvivalMotion motion,SurvivalShipState ship){
            var local=motion.pose;var rotation=ShipRotation(ship);var velocity=ShipPointVelocity(ship,local);var suit=Double3.Rotate(rotation,new Double3(motion.walkVelocityX,motion.walkVelocityY+motion.verticalSpeed,motion.walkVelocityZ));var forward=rotation*SurvivalMovement.Forward(motion);
            motion.pose=SurvivalShipInteriorModel.World(ship,local);motion.ship=null;motion.interior=false;motion.grounded=false;motion.verticalSpeed=0;SurvivalMovement.ResetWalkingVelocity(motion);motion.eva=true;motion.evaVelocityX=velocity.x;motion.evaVelocityY=velocity.y;motion.evaVelocityZ=velocity.z;motion.evaSuitX=suit.x;motion.evaSuitY=suit.y;motion.evaSuitZ=suit.z;
            forward=SurvivalMovement.Tangent(forward,PlanetPrecisionPolicy.Direction(SurvivalVehicleSimulation.Position(motion.pose)));motion.forwardX=forward.x;motion.forwardY=forward.y;motion.forwardZ=forward.z;motion.notice="EVA · WASD thrust · R/C up/down · Shift boost · return through the open rear hatch";
        }
        void StepEva(SurvivalMotion motion,SurvivalInput input,PlanetSurface surface,float dt){
            var position=SurvivalVehicleSimulation.Position(motion.pose);var up=PlanetPrecisionPolicy.Direction(position);var forward=Quaternion.AngleAxis(input.lookX,up)*SurvivalMovement.Tangent(SurvivalMovement.Forward(motion),up);motion.pitch=Mathf.Clamp(motion.pitch-input.lookY,-85,85);var look=Quaternion.AngleAxis(motion.pitch,Vector3.Cross(up,forward))*forward;
            var carrier=new Double3(motion.evaVelocityX,motion.evaVelocityY,motion.evaVelocityZ);var suit=new Double3(motion.evaSuitX,motion.evaSuitY,motion.evaSuitZ);
            SurvivalEvaKinematics.Step(ref position,ref carrier,ref suit,look,up,new Vector3(input.x,input.y,input.z),input.boost,dt,surface.Definition.gravitationalParameter,Config.evaSpeed,Config.evaBoostSpeed,Config.evaAcceleration);
            double floor=surface.Definition.radius+surface.SampleHeight(position)+.05;if(position.Magnitude<=floor){position*=floor/Math.Max(1,position.Magnitude);ClearEva(motion);motion.grounded=true;}else {motion.evaVelocityX=carrier.x;motion.evaVelocityY=carrier.y;motion.evaVelocityZ=carrier.z;motion.evaSuitX=suit.x;motion.evaSuitY=suit.y;motion.evaSuitZ=suit.z;motion.grounded=false;}
            motion.pose.x=position.x;motion.pose.y=position.y;motion.pose.z=position.z;var nextUp=PlanetPrecisionPolicy.Direction(position);forward=Quaternion.FromToRotation(up,nextUp)*forward;motion.forwardX=forward.x;motion.forwardY=forward.y;motion.forwardZ=forward.z;motion.sequence=input.sequence;
        }
        static void StoreEva(SurvivalMotion motion,SurvivalPlayerRecord record){record.eva=motion.eva;record.evaVelocityX=motion.evaVelocityX;record.evaVelocityY=motion.evaVelocityY;record.evaVelocityZ=motion.evaVelocityZ;record.evaSuitX=motion.evaSuitX;record.evaSuitY=motion.evaSuitY;record.evaSuitZ=motion.evaSuitZ;}
        bool SpaceBoarding(Peer peer,SurvivalShipState ship,FramePose local)=>peer.motion.eva&&clock.Tick>=peer.record.evaBoardReadyTick&&SpaceDoorway(ship,local)&&(EvaVelocity(peer.motion)-ShipPointVelocity(ship,local)).Magnitude<=8;
    }
    internal static class SurvivalEvaContacts {
        internal static FramePose Local(SpacePose ship,FramePose pose,long frame){var point=Double3.Rotate(Quaternion.Inverse(ship.rotation),new Double3(pose.x,pose.y,pose.z)-ship.position);return new FramePose{body=pose.body,frame=frame,x=point.x,y=point.y,z=point.z};}
        internal static bool Resolve(SurvivalMotion motion,FramePose previous,SpacePose start,SpacePose end,SurvivalShipInteriorModel model,out float impact){
            impact=0;if(model==null)return false;var from=Local(start,previous,model.assembly.id);var target=Local(end,motion.pose,model.assembly.id);var sample=motion.Copy();sample.pose=target;sample.verticalSpeed=0;sample.grounded=false;var forward=Quaternion.Inverse(end.rotation)*SurvivalMovement.Forward(motion);sample.forwardX=forward.x;sample.forwardY=forward.y;sample.forwardZ=forward.z;model.contacts.Resolve(sample,from,false,Vector3.up);if(sample.pose.Distance(target)<.00001)return false;
            var local=new Double3(sample.pose.x,sample.pose.y,sample.pose.z);var point=end.position+Double3.Rotate(end.rotation,local);var velocity=end.linearVelocity+new Double3(Vector3.Cross(end.angularVelocity,Double3.Rotate(end.rotation,local).Float));var actual=new Double3(motion.evaVelocityX+motion.evaSuitX,motion.evaVelocityY+motion.evaSuitY,motion.evaVelocityZ+motion.evaSuitZ);impact=(float)(actual-velocity).Magnitude;
            if(impact>50){var path=new Double3(target.x-from.x,target.y-from.y,target.z-from.z);var covered=new Double3(sample.pose.x-from.x,sample.pose.y-from.y,sample.pose.z-from.z);double length=path.x*path.x+path.y*path.y+path.z*path.z;float t=(float)(length>1e-9?Math.Max(0,Math.Min(1,(covered.x*path.x+covered.y*path.y+covered.z*path.z)/length)):0);point=start.position+(end.position-start.position)*t+Double3.Rotate(Quaternion.Slerp(start.rotation,end.rotation,t),local);}
            motion.pose.x=point.x;motion.pose.y=point.y;motion.pose.z=point.z;motion.evaVelocityX=velocity.x;motion.evaVelocityY=velocity.y;motion.evaVelocityZ=velocity.z;motion.evaSuitX=motion.evaSuitY=motion.evaSuitZ=0;return true;
        }
    }
}

